// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the wall clock.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to burst tokens and refills at rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    int
	clock    Clock
	maxDelay time.Duration
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNegativeDelay    = errors.New("ratelimit: maxDelay must be >= 0")
)

// New creates a Limiter with the given refill rate (tokens/sec), burst
// capacity, and maximum wait accepted by Reserve (0 disables waiting).
func New(rate float64, burst int, maxDelay time.Duration) (*Limiter, error) {
	return NewWithClock(rate, burst, maxDelay, RealClock())
}

// NewWithClock is New with an injectable clock.
func NewWithClock(rate float64, burst int, maxDelay time.Duration, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if maxDelay < 0 {
		return nil, ErrNegativeDelay
	}
	if clock == nil {
		clock = RealClock()
	}
	now := clock.Now()
	return &Limiter{
		tokens:   float64(burst),
		last:     now,
		rate:     rate,
		burst:    burst,
		clock:    clock,
		maxDelay: maxDelay,
	}, nil
}

// advance refills tokens up to the current time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// Allow reports whether n tokens are available now, without waiting.
func (l *Limiter) Allow(n int) bool {
	return l.AllowN(l.clock.Now(), n)
}

// AllowN reports whether n tokens are available at time t.
func (l *Limiter) AllowN(t time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(t)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Reserve attempts to reserve n tokens. If they are not immediately
// available, it returns the delay after which the reservation becomes
// valid, provided that delay is <= maxDelay; otherwise it fails.
// The returned token is valid at time t plus the delay.
func (l *Limiter) Reserve(n int) (time.Duration, bool) {
	if n < 0 {
		return 0, false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.advance(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		l.tokens -= float64(n)
		return 0, true
	}
	delay := time.Duration(need / l.rate * float64(time.Second))
	if delay > l.maxDelay {
		return 0, false
	}
	l.tokens -= float64(n)
	return delay, true
}

// Tokens returns the number of tokens currently available (approximate
// if other goroutines are consuming concurrently).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
