func TestReserve(t *testing.T) {
	l, fc := newTestLimiter(t, 1, 1)
	l.Allow(1) // drain

	// maxDelay is 0, so any wait fails.
	if _, ok := l.Reserve(1); ok {
		t.Fatal("Reserve with zero maxDelay succeeded, want failure")
	}

	// Rebuild with a maxDelay and verify computed delay.
	l2, fc2 := newTestLimiter(t, 2, 1)
	l2.Allow(1)
	d, ok := l2.Reserve(1)
	if !ok {
