func TestConcurrentAllow(t *testing.T) {
	l, _ := newTestLimiter(t, 100, 100)
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 && allowed > 100 {
		t.Fatalf("allowed %d, exceeds burst", allowed)
	}
	if allowed < 1 {
		t.Fatal("allowed 0, expected some successes")
	}
}
